// contentFactory.js
const API_BASE = "http://127.0.0.1:8000/api";

export const contentFactory = (mode, token) => {
  // Функція для створення FormData з даних статті
  const makeFormData = (data) => {
    const formData = new FormData();

    const safeTitle = data.title || "untitled";
    const slug =
      safeTitle.toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + Date.now();

    formData.append("title", safeTitle);
    formData.append("slug", slug);
    formData.append("content", data.content || "");
    formData.append("excerpt", data.excerpt || "");
    formData.append("is_premium", data.is_premium ? "true" : "false");
    formData.append("type", data.type || "standard");

    if (data.category && mode === "standard") formData.append("category", data.category);
    if (data.channel && mode === "channel") formData.append("channel", data.channel);
    if (data.image) formData.append("image", data.image);

    return formData;
  };

  // Головна функція для створення статті
  return async (articleData) => {
    const formData = makeFormData({
      ...articleData,
      type: mode === "channel" ? "interactive" : "standard",
      category: mode === "standard" ? articleData.category || "sport" : undefined,
      channel: mode === "channel" ? articleData.channel || null : undefined,
    });

    try {
      const res = await fetch(`${API_BASE}/articles/`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: formData,
      });

      const text = await res.text();
      console.log("Сервер повернув:", text);

      if (!res.ok) {
        throw new Error(
          mode === "channel"
            ? "Не вдалося створити статтю для каналу"
            : "Не вдалося створити стандартну статтю"
        );
      }

      return JSON.parse(text);
    } catch (err) {
      console.error("Помилка створення:", err);
      throw err;
    }
  };
};
